import{_ as a,c as o,o as r,a2 as s}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Preguntas frecuentes","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/faq.md","filePath":"es/guide/faq.md","lastUpdated":1793163976000}'),i={name:"es/guide/faq.md"};function n(p,e,t,c,u,l){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h1><p>P: ¿Qué es NueZip?</p><p>R: NueZip es un gestor de archivos profesional para macOS, compatible con la compresión y extracción de múltiples formatos de archivo, incluyendo RAR, ZIP, 7-Zip, TAR, GZIP y BZIP2.</p><p>P: ¿Qué versiones de macOS son compatibles?</p><p>R: NueZip requiere macOS 14 Sonoma o posterior, y está optimizado para chips Apple Silicon (serie M).</p><p>P: ¿Cómo descargo e instalo NueZip?</p><p>R: Descarga desde la <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store</a> (recomendado) o obtén la última versión desde <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a>.</p><p>P: ¿Es gratuito NueZip?</p><p>R: NueZip ofrece una versión de prueba gratuita con funciones básicas. Una compra única desbloquea el conjunto completo de funciones, incluyendo operaciones por lotes, reparación de archivos y cifrado avanzado.</p><p>P: ¿Qué formatos son compatibles?</p><p>R: <strong>Lectura</strong>: RAR, ZIP, 7-Zip, TAR, GZIP, BZIP2, XZ, Zstandard<br><strong>Escritura (comprimir)</strong>: ZIP, 7-Zip, TAR, GZIP, BZIP2, XZ, Zstandard<br> Consulta la <a href="/es/guide/introduction.html">Introducción</a> para ver la matriz completa de formatos.</p><p>P: ¿Puede NueZip crear archivos RAR?</p><p>R: No. NueZip puede <strong>leer</strong> archivos RAR (incluidos los archivos multi-volumen y reparados), pero la compresión RAR no es compatible debido a restricciones de licencia.</p><p>P: ¿Es seguro NueZip para archivos confidenciales?</p><p>R: Sí. NueZip funciona totalmente sin conexión. Todas las operaciones se ejecutan localmente en tu Mac. El cifrado AES-256 está disponible para archivos ZIP protegidos con contraseña.</p><p>P: ¿Sube NueZip mis archivos a la nube?</p><p>R: No. NueZip es una aplicación totalmente sin conexión. Tus archivos nunca se suben a ningún lugar. No se requiere conexión a internet para comprimir o extraer.</p><p>P: ¿Cómo actualizo la app?</p><p>R: Actualiza a través de la Mac App Store (automático) o descarga la última versión desde GitHub Releases.</p><p>P: ¿Cómo informo de errores o solicito funciones?</p><p>R: Abre un issue en el <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">repositorio de GitHub</a>. Por favor incluye tu versión de macOS, versión de NueZip y los pasos para reproducir.</p><p>P: ¿Dónde se almacenan los registros y los datos?</p><p>R: Para compilaciones con sandbox (App Store):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Application Support/com.w3cub.nuezip/</span></span></code></pre></div><p>Las compilaciones de desarrollo pueden escribir registros en la consola.</p><p>Si necesitas más respuestas, por favor abre un issue en el repositorio o consulta la documentación completa.</p>',26)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
